--
-- Table structure for table `sales`
--

DROP TABLE IF EXISTS `sales`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `sales` (
  `id` char(36) NOT NULL,
  `timestamp` datetime NOT NULL,
  `total_amount` decimal(12,2) NOT NULL,
  `payment_method` enum('EFECTIVO','DEBITO','TRANSFERENCIA') NOT NULL,
  `cash_close_id` int(11) DEFAULT NULL,
  `is_cancelled` tinyint(1) NOT NULL DEFAULT 0,
  `cancelled_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_sales_timestamp` (`timestamp`),
  KEY `ix_sales_cash_close_id` (`cash_close_id`),
  CONSTRAINT `sales_ibfk_1` FOREIGN KEY (`cash_close_id`) REFERENCES `cash_closes` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
